const o="zenkamoku-n3-best-workbook",t="w11-d04",n=11,c=4,e="第11週",i="4日目",r=[{type:"summary_comprehension",title:"概要理解",titleEn:"Summary comprehension",pageRef:"p.168",instruction:"問題用紙に何もいんさつされていません。この問題は、ぜんたいとしてどんなないようかを聞く問題です。話の前に質問はありません。まず話を聞いてください。それから、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つえらんでください。",questions:[{number:1,trackId:"N3-92",audioSrc:"/audio/zenkamoku_n3/N3-92.mp3",options:["1","2","3","4"],correct:1,correctOption:"1",script:"女：まず、「お父とうさんにプレゼントを贈おくるか」という質しつ問もんに「はい」と答こたえた人ひとは64％でした。また、プレゼントを贈おくると答こたえた人ひとに「自じ分ぶんのお父とうさんはどんな人ひとか」と質しつ問もんすると、「家か事じを積せっ極きょく的てきに行おこなっている」という答こたえが83％で、プレゼントの金きん額がくも、家か事じをよくするお父とうさんほど高たかいという結けっ果かでした。"},{number:2,trackId:"N3-93",audioSrc:"/audio/zenkamoku_n3/N3-93.mp3",options:["1","2","3","4"],correct:3,correctOption:"3",script:"男：ゆっくり息いきを吸すいながら一いち度ど体からだに力ちからを入いれて、ゆっくり息いきを吐はきながら全ぜん身しんの力ちからを抜ぬいてみてください。これを２、３分ぷん繰くり返かえすと、だんだん眠ねむくなってきますよ。"},{number:3,trackId:"N3-94",audioSrc:"/audio/zenkamoku_n3/N3-94.mp3",options:["1","2","3","4"],correct:2,correctOption:"2",script:"男おとこの留りゅう学がく生せいは「がらがら」という日に本ほん語ごの表ひょう現げんを紹しょう介かいし、女おんなの留りゅう学がく生せいは「他ほかにも面おも白しろい言こと葉ば、見みつけた？」と日に本ほん語ごの表ひょう現げんについて質しつ問もんしている。   33"}]},{type:"utterance_expression",title:"発話表現",titleEn:"Utterance expressions",pageRef:"pp.168-169",instruction:"えを見ながら質問を聞いてください。やじるし（➡）の人は何と言いますか。1から3の中から、最もよいものを一つえらんでください。",questions:[{number:1,trackId:"N3-95",audioSrc:"/audio/zenkamoku_n3/N3-95.mp3",imageSrc:"/images/zenkamoku_n3/w11_d4_q1.jpg",options:["1","2","3"],correct:3,correctOption:"3",script:"この靴くつを履はいてみてもいいですか？：May I try on these shoes?"},{number:2,trackId:"N3-96",audioSrc:"/audio/zenkamoku_n3/N3-96.mp3",imageSrc:"/images/zenkamoku_n3/w11_d4_q2.jpg",options:["1","2","3"],correct:3,correctOption:"3",script:"お湯ゆが出でないんですが。：There’s no hot water (for the shower, so could you do something about it?)"},{number:3,trackId:"N3-97",audioSrc:"/audio/zenkamoku_n3/N3-97.mp3",imageSrc:"/images/zenkamoku_n3/w11_d4_q3.jpg",options:["1","2","3"],correct:3,correctOption:"3",script:"もうすぐ完かん成せいだね。：It’s almost done, isn’t?"},{number:4,trackId:"N3-98",audioSrc:"/audio/zenkamoku_n3/N3-98.mp3",imageSrc:"/images/zenkamoku_n3/w11_d4_q4.jpg",options:["1","2","3"],correct:2,correctOption:"2",script:"先せん生せいに伝つたえてほしいんだけど。：I want you to tell the teacher something (but will you do it?)"}]}],a={bookId:o,chapterId:t,week:11,day:4,weekTitle:e,dayTitle:"4日目",subSections:r};export{o as bookId,t as chapterId,c as day,i as dayTitle,a as default,r as subSections,n as week,e as weekTitle};
